fn prime_num(n: u64) -> bool {
    // Handle edge cases: n >= 2 guaranteed.
    // Special case to avoid pointless loop: 2 is prime.
    if n == 2 {
        return true;
    }

    // Calculate the integer square root of n.
    // Using f64 sqrt is fine since u64 max fits well in f64.
    // floor(sqrt(n))
    let limit = (n as f64).sqrt() as u64;

    // Check divisors from 2 up to and including limit
    for k in 2..=limit {
        if n % k == 0 {
            return false; // divisor found, n is not prime
        }
    }

    // No divisors found, n is prime
    true
}